"use strict";

// The package's whole callable API is chosen AT RUNTIME by a resolvable
// LOCAL CALL whose own body always throws -- but, unlike RWF-016's,
// RWF-017's, RWF-018's and RWF-019's fixtures, the call sits on no class
// ELEMENT at all. It is the class's `extends` HERITAGE expression, and the
// class body is completely EMPTY:
//
//     class Mode extends bail() {}
//
// ClassDefinitionEvaluation evaluates the heritage expression FIRST, before
// any element exists: the superclass value has to be in hand before the
// prototype chain can be built, so it runs strictly before every computed
// key (RWF-019), every static field initializer (RWF-018) and every static
// block (RWF-015). An analyzer that reads class-definition-time execution
// off the ELEMENTS therefore has nothing here to fire on -- there are no
// elements.
// See fixtures/commonjs-circular-import-class-heritage-throw-ground-truth/
// for a real node-executed proof, including the measured evaluation ORDER.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw -- definitely abrupt by RWF-016's own model, unchanged.
function bail() {
  throw new Error("fast mode is not supported here");
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // Evaluating this class definition necessarily invokes `bail()` before
  // anything else about the class happens. It never returns, `Mode` is
  // never bound, and module evaluation on this branch ends here.
  class Mode extends bail() {}
}

module.exports = safeOp;
